test("normalizes literal tokens with stable semantic styles", () => {
  const result = normalizeTokens(["TODO", "FIXME", "CUSTOM"], true);
  assert.deepEqual(result.tokens.map(({ token, style }) => ({ token, style })), [
    { token: "TODO", style: "info" },
    { token: "FIXME", style: "error" },
    { token: "CUSTOM", style: "info" },
  ]);
  assert.equal(result.rejected, 0);
})

test("rejects unsafe, duplicate, and excessive tokens", () => {
  const values = ["TODO", "todo", "", "two words", "bad\u0000token", "x".repeat(65), 42];
  const result = normalizeTokens(values, false);
  assert.deepEqual(result.tokens.map((entry) => entry.token), ["TODO"]);
  assert.equal(result.rejected, 6);
})

test("normalizes bounded glob lists and numeric settings", () => {
  assert.deepEqual(normalizeGlobList(["**/*.ts", "**/*.ts", "", "x\u0000y", 3], ["fallback"]), ["**/*.ts"]);
  assert.deepEqual(normalizeGlobList(undefined, ["fallback"]), ["fallback"]);
  assert.equal(boundedInteger(10.9, 5, 1, 10), 10);
  assert.equal(boundedInteger(-5, 5, 1, 10), 1);
  assert.equal(boundedInteger("10", 5, 1, 10), 5);
})

test("detects NUL and dense control-byte binary prefixes", () => {
  assert.equal(isLikelyBinary(new Uint8Array([65, 0, 66])), true);
  assert.equal(isLikelyBinary(new Uint8Array([1, 2, 3, 4, 65])), true);
  assert.equal(isLikelyBinary(new TextEncoder().encode("// TODO normal text\n")), false);
})

test("infers supported language adapters from URI paths", () => {
  assert.equal(inferLanguageId("/workspace/src/app.tsx"), "typescriptreact");
  assert.equal(inferLanguageId("/workspace/Dockerfile.dev"), "dockerfile");
  assert.equal(inferLanguageId("/workspace/Makefile"), "makefile");
  assert.equal(inferLanguageId("/workspace/unknown.data"), "plaintext");
})

test("groups files and annotations in deterministic ordinal order", () => {
  const index = new AnnotationIndex();
  index.replaceSnapshot([
    file("file:///z.ts", "// TODO z"),
    file("file:///A.ts", "// FIXME first\n// TODO second"),
  ], complete);
  assert.deepEqual(index.groups().map((group) => group.uri), ["file:///A.ts", "file:///z.ts"]);
  assert.deepEqual(index.groups()[0]!.annotations.map((annotation) => annotation.token), ["FIXME", "TODO"]);
  assert.equal(index.total, 3);
})

test("filters tokens, resolves stable IDs, and removes files", () => {
  const index = new AnnotationIndex();
  index.replaceSnapshot([file("file:///a.ts", "// TODO a\n// FIXME b")], complete);
  const todo = index.all(new Set(["TODO"]));
  assert.equal(todo.length, 1);
  assert.equal(index.findById(todo[0]!.id)?.message, "a");
  index.removeFile("file:///a.ts");
  assert.equal(index.total, 0);
})

test("case-sensitive filters distinguish TODO and todo while an empty filter stays empty", () => {
  const index = new AnnotationIndex();
  const result = matchAnnotations("// TODO upper\n// todo lower", {
    uri: "file:///case.ts", languageId: "typescript", source: "workspace-scan",
    tokens: normalizeTokens(["TODO", "todo"], true).tokens, caseSensitive: true,
    maxMessageLength: 500, maxResults: 100,
  });
  index.replaceSnapshot([{ uri: "file:///case.ts", source: "workspace-scan", ...result }], complete);
  assert.deepEqual(index.all(new Set(["TODO"])).map((annotation) => annotation.message), ["upper"]);
  assert.deepEqual(index.all(new Set(["todo"])).map((annotation) => annotation.message), ["lower"]);
  assert.equal(index.all(new Set(["todo"]), false).length, 2);
  assert.equal(index.all(new Set()).length, 0);
})

test("replaces one file atomically and records result truncation", () => {
  const index = new AnnotationIndex();
  index.replaceSnapshot([file("file:///a.ts", "// TODO old")], complete);
  const truncated = index.replaceFile(file("file:///a.ts", "// TODO one\n// FIXME two"), 1);
  assert.equal(truncated, true);
  assert.equal(index.total, 1);
  assert.deepEqual(index.status.partialReasons, ["result-limit"]);
})

test("open-document replacement supersedes disk results", () => {
  const index = new AnnotationIndex();
  index.replaceSnapshot([file("file:///a.ts", "// TODO disk")], complete);
  const open = file("file:///a.ts", "// FIXME unsaved");
  index.replaceFile({ ...open, source: "open-document", annotations: open.annotations.map((annotation) => ({ ...annotation, source: "open-document" })) }, 10);
  assert.deepEqual(index.all().map(({ token, message, source }) => ({ token, message, source })), [
    { token: "FIXME", message: "unsaved", source: "open-document" },
  ]);
})

test("leaves per-file truncation classification to the scan owner", () => {
  const index = new AnnotationIndex();
  index.replaceSnapshot([], complete);
  const limited = file("file:///a.ts", "// TODO one");
  assert.equal(index.replaceFile({ ...limited, truncated: true }, 10), true);
  assert.deepEqual(index.status.partialReasons, []);
})

test("finds slash comments while excluding strings, templates, and regex literals", () => {
  const source = [
    'const text = "// TODO hidden";',
    "const template = `/* HACK hidden */`;",
    "const pattern = /\\/\\/ FIXME hidden/; // FIXME real failure",
    "/* REVIEW inspect this */",
  ].join("\n");
  const result = match(source, "typescript");
  assert.deepEqual(result.annotations.map(({ token, message, line }) => ({ token, message, line })), [
    { token: "FIXME", message: "real failure", line: 2 },
    { token: "REVIEW", message: "inspect this", line: 3 },
  ]);
})

test("finds hash comments without matching quoted hashes", () => {
  const result = match('print("# TODO hidden")  # HACK temporary\n# NOTE: explain', "python");
  assert.deepEqual(result.annotations.map(({ token, message }) => ({ token, message })), [
    { token: "HACK", message: "temporary" },
    { token: "NOTE", message: "explain" },
  ]);
})

test("finds markup and stylesheet comments only", () => {
  const html = match('<div title="TODO hidden"></div><!-- TODO: visible -->', "html");
  const css = match('.x::after { content: "FIXME hidden"; } /* FIXME visible */', "css");
  assert.equal(html.annotations.length, 1);
  assert.equal(html.annotations[0]!.message, "visible");
  assert.equal(css.annotations.length, 1);
  assert.equal(css.annotations[0]!.message, "visible");
})

test("ignores fenced Markdown and reads HTML comments outside fences", () => {
  const source = "```ts\n// TODO hidden\n```\n<!-- NOTE visible -->";
  const result = match(source, "markdown");
  assert.deepEqual(result.annotations.map(({ token, line }) => ({ token, line })), [{ token: "NOTE", line: 3 }]);
})

test("enforces boundaries and keeps owner syntax as message text", () => {
  const result = match("// TODONT no\n// TODO(@ana): owner text\n// TODO: plain", "javascript", ["TODO"]);
  assert.deepEqual(result.annotations.map(({ message, line }) => ({ message, line })), [
    { message: "(@ana): owner text", line: 1 },
    { message: "plain", line: 2 },
  ]);
})

test("supports case-insensitive custom literal tokens", () => {
  const result = match("// todo lower\n// @Review custom", "javascript", ["TODO", "@REVIEW"], false);
  assert.deepEqual(result.annotations.map((annotation) => annotation.token), ["todo", "@Review"]);
})

test("preserves Unicode messages, CRLF positions, and stable value-free IDs", () => {
  const result = match("\uFEFF// TODO: café ☕\r\n// FIXME: résumé", "javascript");
  assert.deepEqual(result.annotations.map(({ line, character, message }) => ({ line, character, message })), [
    { line: 0, character: 4, message: "café ☕" },
    { line: 1, character: 3, message: "résumé" },
  ]);
  assert.match(result.annotations[0]!.id, /^annotation:[0-9a-f]{16}$/u);
  assert.equal(result.annotations[0]!.id.includes("café"), false);
})

test("bounds messages and per-file result counts", () => {
  const long = match(`// TODO ${"x".repeat(600)}`, "javascript");
  assert.equal(Array.from(long.annotations[0]!.message).length, 500);
  assert.equal(long.annotations[0]!.messageTruncated, true);
  const limited = match("// TODO one\n// TODO two", "javascript", ["TODO"], true, 1);
  assert.equal(limited.annotations.length, 1);
  assert.equal(limited.truncated, true);
})

test("handles pathological long non-boundary runs without recursion", () => {
  const result = match(`// ${"A".repeat(100_000)}`, "javascript", ["A"]);
  assert.equal(result.annotations.length, 0);
})

test("uses Unicode-aware token boundaries", () => {
  const result = match("// 前修正後 hidden\n// 修正 visible", "javascript", ["修正"]);
  assert.deepEqual(result.annotations.map(({ message, line }) => ({ message, line })), [{ message: "visible", line: 1 }]);
})

